def _wrap_text(text: str, font_name: str, font_size: float, max_width: float) -> list:
    """Wrap text to fit within max_width, return list of lines."""
    lines = []
    for paragraph in str(text).splitlines():
        if not paragraph.strip():
            lines.append("")
            continue
        wrapped = simpleSplit(paragraph, font_name, font_size, max_width)
        lines.extend(wrapped if wrapped else [""])
    return lines

def get_ordinal_suffix(day: int) -> str:
    if 11 <= (day % 100) <= 13:
        return 'th'
    return {1: 'st', 2: 'nd', 3: 'rd'}.get(day % 10, 'th')

def format_date(date_str: str) -> str:
    try:
        for fmt in ["%Y-%m-%d", "%d-%m-%Y", "%d/%m/%Y", "%Y/%m/%d", "%d-%m-%y"]:
            try:
                parsed = datetime.strptime(date_str, fmt)
                day = parsed.day
                suffix = get_ordinal_suffix(day)
                return parsed.strftime(f"{day}{suffix} %B %Y")
            except ValueError:
                continue
        return date_str
    except Exception:
        return date_str

def call_gemini(model, prompt, retries=3):
    for i in range(retries):
        try:
            response = model.generate_content(
                prompt,
                generation_config={
                    "temperature": 0.4,
                    "top_p": 0.9,
                }
            )
            text = response.text.strip()
            text = re.sub(r'^```(?:json)?\s*', '', text)
            text = re.sub(r'\s*```$', '', text)
            return text

        except Exception as e:
            if "429" in str(e):
                time.sleep(40)
            else:
                raise e
    raise Exception("Gemini failed after retries")

